<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  fmt.</span><span style="--shiki-light:#8250DF;--shiki-dark:#D2A8FF;">Printf</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">(</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;1. 整個結構體的大小 (Size): </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">%d</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> bytes</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\n</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, unsafe.</span><span style="--shiki-light:#8250DF;--shiki-dark:#D2A8FF;">Sizeof</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">(d))</span></span>
